paragraph.math:
$$\begin{array}{l}
  {f\left( {x + h} \right) - f(x) = x^{2} + 2xh + h^{2} - 4x - 4h - {({x^{2} - 4x})}} \\
  {\phantom{f\left( {x + h} \right) - f(x)} = 2\mathit{xh} + h^{2} - 4h = h\left( {2x + h - 4} \right)}
  \end{array}$$

$$\begin{array}{l}
  {\frac{f\left( {t + h} \right) - f(t)}{h} = \frac{2\left( {t + h} \right)^{2} - 2t^{2}}{h}} \\
  {\phantom{\frac{f\left( {t + h} \right) - f(t)}{h}} = \frac{2t^{2} + 4th + 2h^{2} - 2t^{2}}{h}} \\
  {\phantom{\frac{f\left( {t + h} \right) - f(t)}{h}} = 4t + 2h}
  \end{array}$$

$$\begin{array}{l}
  {\lim\limits_{h\rightarrow 0}\frac{f\left( {t + h} \right) - f(t)}{h} = \lim\limits_{h\rightarrow 0}\left( {4t + 2h} \right)\qquad{\text{Use the results from part~}(a).}} \\
  {\phantom{\lim\limits_{h\rightarrow 0}\frac{f\left( {t + h} \right) - f(t)}{h}} = 4t}
  \end{array}$$

$$\begin{array}{l}
  {\lim\limits_{h\rightarrow 0}\frac{f\left( {x + h} \right) - f(x)}{h} = \lim\limits_{h\rightarrow 0}\left( {- 2x - h} \right)\qquad{\text{Use the results from part~}(a).}} \\
  {\phantom{\lim\limits_{h\rightarrow 0}\frac{f\left( {x + h} \right) - f(x)}{h}} = - 2x}
  \end{array}$$
